INSERT INTO admin_api_keys (
    id, name, key_prefix, key_hash, owner_user_id, scopes, created_by, created_at,
    expires_at
) VALUES (
    #{id}, #{name}, #{keyPrefix}, #{keyHash}, #{ownerUserId},
    COALESCE(CAST(#{scopes} AS TEXT), '[]')::jsonb, #{createdBy}, #{createdAt}, #{expiresAt}
)

mapper.select:
SELECT 
FROM admin_api_keys k
WHERE k.key_hash = #{keyHash}

mapper.update:
UPDATE admin_api_keys
SET revoked_at = COALESCE(revoked_at, #{revokedAt})
WHERE id = #{id}

UPDATE admin_api_keys
SET last_used_at = #{usedAt}
WHERE id = #{id}
  AND (last_used_at IS NULL OR last_used_at < #{staleBefore})
